using Microsoft.EntityFrameworkCore;using GrapheneTrace.Areas.Identity.Data;using GrapheneTrace.Services.Interfaces;using GrapheneTrace.Models.Admin;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc.Rendering;using GrapheneTrace.Data; using GrapheneTrace.Models.Database; using GrapheneTrace.Enums;using GrapheneTrace.Models;namespace GrapheneTrace.Services{    public class AdminService : IAdminService    {        private readonly ApplicationDbContext _context;        private readonly UserManager<ApplicationUser> _userManager;                public AdminService(UserManager<ApplicationUser> userManager, ApplicationDbContext context)        {            _userManager = userManager;            _context = context;        }        public async Task<bool> UpdateUser(EditUserViewModel model)        {            var user = await _userManager.FindByIdAsync(model.Id.ToString());            if (user == null)                return false;            user.Email = model.Email;            user.UserName = model.Email;            user.DateOfBirth = model.DateOfBirth;            user.Name = model.Name;            var userRoles = await _userManager.GetRolesAsync(user);            await _userManager.AddToRolesAsync(user, model.SelectedRoles.Except(userRoles));            await _userManager.RemoveFromRolesAsync(user, userRoles.Except(model.SelectedRoles));            if (!string.IsNullOrEmpty(model.NewPassword))            {                if (model.NewPassword != model.ConfirmPassword)                    return false;                foreach (var validator in _userManager.PasswordValidators)                {                    var result = await validator.ValidateAsync(_userManager, user, model.NewPassword);                    if (!result.Succeeded)                    {                        return false;                    }                }                                await _userManager.RemovePasswordAsync(user);                await _userManager.AddPasswordAsync(user, model.NewPassword);            }            var updateResult = await _userManager.UpdateAsync(user);            return updateResult.Succeeded;        }                public async Task UpdatePatientClinicianLinks(List<int> idsToAdd, List<int> idsToRemove, int primaryUserId, bool isManagingPatient)        {            if (idsToAdd.Count > 0)            {                var newLinks = idsToAdd.Select(id => isManagingPatient switch                {                    true  => new PatientClinician { PatientId = primaryUserId, ClinicianId = id },                    false => new PatientClinician { PatientId = id, ClinicianId = primaryUserId }                });                _context.PatientClinician.AddRange(newLinks);            }            if (idsToRemove.Count > 0)            {                var linksToRemoveQuery = isManagingPatient switch                {                    true => _context.PatientClinician.Where(pc =>                        pc.PatientId == primaryUserId && idsToRemove.Contains(pc.ClinicianId)),                    false => _context.PatientClinician.Where(pc =>                        pc.ClinicianId == primaryUserId && idsToRemove.Contains(pc.PatientId))                };                var linksToRemove = await linksToRemoveQuery.ToListAsync();                _context.PatientClinician.RemoveRange(linksToRemove);            }            await _context.SaveChangesAsync();        }        public async Task<List<int>> GetAlreadyLinkedUsers(int id, UserType type)        {            return type switch            {                UserType.Clinician => await _context.PatientClinician.Where(pc => pc.PatientId == id)                    .Select(pc => pc.ClinicianId)                    .ToListAsync(),                UserType.Patient => await _context.PatientClinician.Where(pc => pc.ClinicianId == id)                    .Select(pc => pc.PatientId)                    .ToListAsync(),                _ => []            };        }        public IList<SelectListItem> GetLinkSelectionList(IList<ApplicationUser> users, List<int> linkedIds, LinkFilter type)        {            var filteredUsers = type switch            {                LinkFilter.Assigned => users.Where(u => linkedIds.Contains(u.Id)),                LinkFilter.Available => users.Where(u => !linkedIds.Contains(u.Id)),                _ => []            };                        IList<SelectListItem> result = filteredUsers                .Select(u => new SelectListItem                {                    Text = $"{u.Name} ({u.Email})",                    Value = u.Id.ToString()                })                .ToList();            return result;        }                // Services/AdminService.cs        public async Task<List<UserViewModel>> GetAdminDashboardUsersAsync(string searchString)        {            var query = _userManager.Users.AsNoTracking();                        if (!string.IsNullOrEmpty(searchString))            {                query = query.Where(u =>                     u.Email.Contains(searchString) ||                     u.Name.Contains(searchString) ||                    u.Id.ToString() == searchString                );            }                        var users = await query.Select(u => new UserViewModel            {                Id = u.Id,                Email = u.Email ?? "",                Name = u.Name ?? string.Empty,                DateOfBirth = u.DateOfBirth,                PatientLinkCount = _context.PatientClinician.Count(pc => pc.PatientId == u.Id),                ClinicianLinkCount = _context.PatientClinician.Count(pc => pc.ClinicianId == u.Id)            })            .ToListAsync();            foreach (var userVm in users)            {                var user = await _userManager.FindByIdAsync(userVm.Id.ToString());                if (user != null)                {                    var roles = await _userManager.GetRolesAsync(user);                    userVm.Roles = roles.ToList();                }            }            if (!string.IsNullOrEmpty(searchString))            {                var upperSearch = searchString.ToUpper();                users = users.Where(u =>                     u.Email.ToUpper().Contains(upperSearch) ||                    u.Name.ToUpper().Contains(upperSearch) ||                    u.Roles.Any(r => r.ToUpper().Contains(upperSearch))                ).ToList();            }            return users;        }            }}